<?php namespace App\Http\Controllers\Api\V1\Ai; use App\Http\Controllers\Controller; use App\Http\Requests\Ai\GenerateReportSummaryRequest; use App\Models\Report; use App\Services\AiReports\ReportAnalysisService; use App\Support\ApiResponse; use Illuminate\Support\Facades\Gate; class AiReportController extends Controller { protected $analysisService; public function __construct(ReportAnalysisService $analysisService) { $this->analysisService = $analysisService; } public function summarize(GenerateReportSummaryRequest $request, Report $report) { Gate::authorize("summarize", $report); $summary = $this->analysisService->summary($report); return ApiResponse::success("Report summary generated successfully", $summary); } }